-- Readonly. false prerequisites means STOP; inspect adaptation-v2 deployment separately.
SELECT (to_regclass('public.curriculum_topics') IS NOT NULL AND to_regclass('public.course_curriculum_units') IS NOT NULL AND to_regtype('public.question_course_scope') IS NOT NULL AND to_regclass('storage.objects') IS NOT NULL AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261026000000' AND name='question_practice_adaptation_v2' AND cardinality(statements)=1 AND md5(statements[1])='354934137b8be264f4b1b2cf58d36b2e') AND (coalesce((SELECT md5(prosrc)='86b03f6166861027f963df9712895e75' FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_expected_seconds(public.question_difficulty)')),false) AND coalesce((SELECT md5(prosrc)='89c8704956cbf6a85fafb47063e1f9af' FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_target(bigint,bigint)')),false) AND coalesce((SELECT md5(prosrc)='a18312b9fe60c31fbdde267d9241e6ae' FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_signals()')),false) AND coalesce((SELECT md5(prosrc)='1162f028c31bdeab0a9fdd0e77b48089' FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_snapshot(uuid)')),false) AND coalesce((SELECT md5(prosrc)='d4088db3fa9026ae6dd0017bc05e6295' FROM pg_proc WHERE oid=to_regprocedure('public.submit_question_practice_v2(uuid,uuid,uuid,integer,jsonb,boolean)')),false) AND coalesce((SELECT md5(prosrc)='3c38ab52a179bc0485a2026f5675b620' FROM pg_proc WHERE oid=to_regprocedure('public.start_question_practice(uuid,uuid)')),false))) AS prerequisites_match,(NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261027000000') AND NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261028000000') AND NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261029000000') AND NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261030000000')) AS migrations_not_recorded,to_regclass('public.course_topic_content') IS NULL AS content_objects_absent,to_regprocedure('public.question_practice_snapshot_questions(uuid)') IS NULL AS practice_objects_absent,NOT EXISTS(SELECT 1 FROM storage.buckets WHERE id='course-games') AS game_bucket_absent;
SELECT schemaname,tablename,policyname,cmd,roles,qual,with_check FROM pg_policies WHERE (schemaname='public' AND tablename IN ('courses','course_videos')) OR (schemaname='storage' AND tablename='objects') ORDER BY schemaname,tablename,policyname;
